local({
  partner_female <- Reduce(
    `|`,
    lapply(12:20, function(i) {
      as.numeric(tbl[[sprintf("b7rtok%d", i)]]) %in% c(1, 2) & as.numeric(tbl[[sprintf("b7sex%d", i)]]) %in% 2
    })
  )
  case_when(
    wave == "age16" ~ recode_values(as.numeric(t8.2), 1:3 ~ "Employed", 4:9 ~ "Not employed", default = "Unknown"),
    wave == "child2004" & as.numeric(bd7sex) == 2 ~ recode_values(
      as.numeric(bd7ecact),
      1:4 ~ "Employed",
      c(5, 6, 8, 9, 10, 11) ~ "Not employed",
      default = "Unknown"
    ),
    wave == "child2004" & partner_female ~ recode_values(
      as.numeric(bd7potha),
      c(1:4, 12:14, 17) ~ "Employed",
      c(5, 6, 8:11, 15, 16, 18, 19) ~ "Not employed",
      default = "Unknown"
    ),
    .default = "Unknown"
  )
})

local({
  people <- sprintf("oa7%d", 2:12)
  person <- rep(NA_character_, nrow(tbl))
  for (code in c(2, 14, 22)) {
    for (p in people) {
      hit <- is.na(person) &
        as.numeric(tbl[[paste0(p, ".1")]]) %in% code &
        (code != 22 | as.numeric(tbl[[paste0(p, ".4")]]) %in% 2)
      person[hit] <- p
    }
  }
  birth_year <- rep(NA_real_, nrow(tbl))
  birth_month <- rep(NA_real_, nrow(tbl))
  for (p in people) {
    sel <- person %in% p
    birth_year[sel] <- as.numeric(tbl[[paste0(p, ".5b")]])[sel]
    birth_month[sel] <- as.numeric(tbl[[paste0(p, ".5a")]])[sel]
  }
  born <- birth_year + if_else(is.na(birth_month), 0.5, (birth_month - 0.5) / 12)
  asked <- coalesce(
    as.numeric(odoc_yr) + (as.numeric(odoc_mt) - 0.5) / 12,
    as.numeric(pdoc_yr) + (as.numeric(pdoc_mt) - 0.5) / 12,
    as.numeric(tdoc_yr) + (as.numeric(tdoc_mt) - 0.5) / 12
  )
  partner_age <- rep(NA_real_, nrow(tbl))
  for (i in 12:20) {
    hit <- is.na(partner_age) &
      as.numeric(tbl[[sprintf("b7rtok%d", i)]]) %in% c(1, 2) &
      as.numeric(tbl[[sprintf("b7sex%d", i)]]) %in% 2
    partner_age[hit] <- as.numeric(tbl[[sprintf("b7rage%d", i)]])[hit]
  }
  case_when(
    wave == "age16" ~ asked - born,
    wave == "child2004" ~ if_else(as.numeric(bd7sex) %in% 2, as.numeric(b7rage11), partner_age) + 0.5
  )
})

local({
  early <- rep(NA, nrow(tbl))
  for (b in 1:3) {
    same <- as.numeric(tbl[[paste0("b7lhhn1", b)]]) == as.numeric(b7chdid)
    same[is.na(same)] <- FALSE
    value <- case_when(
      as.numeric(tbl[[paste0("b7prgf1", b)]]) == 1 & as.numeric(tbl[[paste0("b7prgg1", b)]]) >= 4 ~ TRUE,
      as.numeric(tbl[[paste0("b7prgf1", b)]]) == 1 & as.numeric(tbl[[paste0("b7prgg1", b)]]) %in% 1:3 ~ FALSE,
      as.numeric(tbl[[paste0("b7prgf1", b)]]) %in% c(2, 3) ~ FALSE
    )
    early[is.na(early) & same] <- value[is.na(early) & same]
  }
  if_else(wave == "child2004", as.character(early), NA_character_)
})

local({
  linked <- Reduce(
    `|`,
    lapply(1:3, function(b) {
      same <- as.numeric(tbl[[paste0("b7lhhn1", b)]]) == as.numeric(b7chdid)
      !is.na(same) & same
    })
  )
  smoked <- case_when(
    as.numeric(bd7smk12) == 1 | as.numeric(bd7smk13) == 1 ~ "TRUE",
    as.numeric(bd7smk12) == 0 & as.numeric(bd7smk13) == 0 ~ "FALSE"
  )
  if_else(wave == "child2004" & linked, smoked, NA_character_)
})
